// Indiana Nov 3, 2026 ballot data (public/data/in/ballots/), generated by scripts/build-indiana.mjs
// from the Indiana Election Division's results site. One file per county plus _statewide.json.
// Preview only until Indiana is approved for launch — see INDIANA_ENABLED.

import { countySlug } from './officialBallot'

// Off in production until approved; on for localhost and Vercel preview deployments
export const INDIANA_ENABLED = import.meta.env?.VITE_ENABLE_INDIANA === '1' ||
  (typeof window !== 'undefined' && /^(localhost|127\.0\.0\.1)$|\.vercel\.app$/.test(window.location.hostname))

const cache = new Map()
function base() {
  return (typeof window !== 'undefined' && window.Capacitor)
    ? 'https://www.offorandbythepeople.com/'
    : (import.meta.env?.BASE_URL || '/').replace(/\/?$/, '/')
}
function load(file) {
  if (!cache.has(file)) {
    cache.set(file, fetch(`${base()}data/in/ballots/${file}.json`).then(r => (r.ok ? r.json() : null)).catch(() => null))
  }
  return cache.get(file)
}

export async function loadIndianaBallotData(county) {
  const slug = countySlug(county)
  if (!slug) return null
  const [countyData, statewide] = await Promise.all([load(slug), load('_statewide')])
  return countyData && statewide ? { county: countyData, statewide } : null
}

const norm = s => String(s || '').toLowerCase().replace(/\b(township|twp|town|city|of|the)\b/g, ' ').replace(/[^a-z0-9]+/g, ' ').trim()
const GENERIC = /\b(community|consolidated|school|schools|corporation|corp|metropolitan|district|of|the|county|united|public|msd|csc|sc|cs)\b/g
const schoolTokens = (s, county) => norm(s).replace(GENERIC, ' ').split(/\s+/)
  .filter(t => t.length >= 3 && t !== norm(county))

// Public-question plain-English summaries (official ballot language is shown alongside)
const STATE_QUESTIONS = {
  'Public Question #1': {
    name: 'Public Question 1 — Bail restrictions (constitutional amendment)',
    description: 'Would let judges deny bail to people charged with crimes other than murder or treason when the proof is evident or presumption strong AND the state shows by clear and convincing evidence that no release conditions would keep others or the community safe.',
    yesVote: 'YES amends the Indiana Constitution so judges can hold more defendants without bail if the state proves no release conditions would keep the public safe.',
    noVote: 'NO keeps the current rule: only people charged with murder or treason can be denied bail on that basis.',
  },
  'Public Question #2': {
    name: 'Public Question 2 — County judges must live in their county (constitutional amendment)',
    description: 'Would require judges of courts that serve a county to live in that county.',
    yesVote: 'YES adds a constitutional requirement that county-level judges reside in the county they serve.',
    noVote: 'NO leaves residency rules for county judges as they are now.',
  },
}

function toProposal(q, county) {
  const known = q.statewide && STATE_QUESTIONS[q.name]
  const retention = /retention/i.test(q.type)
  return {
    id: q.id,
    name: known?.name || q.name,
    type: retention ? 'Judicial Retention' : q.statewide ? 'Constitutional Amendment' : 'Local Public Question',
    jurisdiction: q.statewide ? 'Statewide' : county,
    division: q.statewide ? 'State' : retention ? 'Judicial' : 'Local',
    category: retention ? 'judicial' : q.statewide ? 'constitution' : 'education',
    description: known?.description || (retention ? 'Vote YES to keep this judge in office or NO to remove them.' : 'Local public question — read the official ballot language below.'),
    yesVote: known?.yesVote || (retention ? 'Keep the judge in office for another term.' : ''),
    noVote: known?.noVote || (retention ? 'Remove the judge from office.' : ''),
    ballotLanguage: q.ballotLanguage,
    official: true,
    status: 'confirmed',
  }
}

// Build a voter's Indiana ballot from their geocoded address.
export function getIndianaBallot(data, geo, districts) {
  if (!data || !geo) return { matched: false, races: [], proposals: [] }
  const { county, statewide } = data
  const cd = Number(districts?.congressional ?? geo.district)
  const ss = Number(districts?.stateSenate ?? geo.stateUpperDistrict)
  const sh = Number(districts?.stateHouse ?? geo.stateLowerDistrict)

  const stateRaces = statewide.races.filter(r =>
    r.scope === 'state' ||
    (r.scope === 'congressional' && r.district === cd) ||
    (r.scope === 'stateSenate' && r.district === ss) ||
    (r.scope === 'stateHouse' && r.district === sh))

  const twp = norm(geo.countySubdivision)
  const place = norm(geo.place)
  const target = schoolTokens(geo.schoolDistrict, county.county)
  const schoolRaces = county.races.filter(r => r.scope === 'school')
  const schoolMatch = r => schoolTokens(r.area, county.county).some(t => target.includes(t))
  const schoolKnown = target.length && schoolRaces.some(schoolMatch)

  const local = county.races.filter(r => {
    if (r.scope === 'county') return true
    if (r.scope === 'township') return !!twp && norm(r.area) === twp
    if (r.scope === 'town' || r.scope === 'city') return !!place && norm(r.area) === place
    if (r.scope === 'school') return schoolKnown ? schoolMatch(r) : false
    return false
  })

  const proposals = county.referendums
    .filter(q => q.statewide || /retention/i.test(q.type) ||
      (schoolKnown ? schoolTokens(q.name, county.county).some(t => target.includes(t)) : true))
    .map(q => toProposal(q, `${county.county} County`))
    .sort((a, b) => (a.division === 'State' ? 0 : 1) - (b.division === 'State' ? 0 : 1))

  return {
    matched: true,
    jurisdiction: [geo.place, geo.countySubdivision && `${geo.countySubdivision} Township`].filter(Boolean)[0] || `${county.county} County`,
    stateRaces,
    races: local,
    proposals,
    schoolMatched: !!schoolKnown,
    unmatchedSchoolRaces: schoolKnown ? [] : schoolRaces,
    electionOffice: county.electionOffice,
    source: county.source,
  }
}
